Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "background": null,
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "datum.severity_rank != null && datum.severity_rank <= 12"
    },
    {
      "calculate": "datum.owner_view === ''confirmed'' ? ''Owners: confirmed only'' : ''Owners: unknown counted as public''",
      "as": "group"
    },
    {
      "calculate": "(datum.benchmark / 1000) + ''k \u00b7 '' + datum.beyond_km + '' km''",
      "as": "setting"
    },
    {
      "calculate": "datum.action === datum.action_low ? ''Same action'' : ''Action changes''",
      "as": "res"
    }
  ],
  "facet": {
    "column": {
      "field": "group",
      "type": "nominal",
      "sort": [
        "Owners: confirmed only",
        "Owners: unknown counted as public"
      ],
      "title": null,
      "header": {
        "labelFont": "Segoe UI",
        "labelFontSize": 11,
        "labelFontWeight": "bold",
        "labelOrient": "top",
        "labelPadding": 8
      }
    }
  },
  "spec": {
    "width": {
      "step": 17
    },
    "height": {
      "step": 24
    },
    "mark": {
      "type": "rect",
      "stroke": "#FFFFFF",
      "strokeWidth": 2,
      "cursor": "pointer"
    },
    "encoding": {
      "x": {
        "field": "setting",
        "type": "ordinal",
        "sort": [
          "10k \u00b7 10 km",
          "10k \u00b7 15 km",
          "10k \u00b7 20 km",
          "20k \u00b7 10 km",
          "20k \u00b7 15 km",
          "20k \u00b7 20 km",
          "30k \u00b7 10 km",
          "30k \u00b7 15 km",
          "30k \u00b7 20 km"
        ],
        "axis": {
          "orient": "bottom",
          "labelAngle": -60,
          "title": null,
          "labelFont": "Segoe UI",
          "labelFontSize": 9
        }
      },
      "y": {
        "field": "lga_name",
        "type": "nominal",
        "sort": {
          "field": "severity_rank",
          "op": "min"
        },
        "axis": {
          "title": null,
          "labelFont": "Segoe UI",
          "labelFontSize": 11
        }
      },
      "color": {
        "field": "res",
        "type": "nominal",
        "scale": {
          "domain": [
            "Same action",
            "Action changes"
          ],
          "range": [
            "#0E6F78",
            "#E8B4AF"
          ]
        },
        "legend": {
          "orient": "bottom",
          "title": null,
          "labelFont": "Segoe UI"
        }
      },
      "tooltip": [
        {
          "field": "lga_name",
          "title": "LGA"
        },
        {
          "field": "group",
          "title": "Owners"
        },
        {
          "field": "setting",
          "title": "Target \u00b7 hospital limit"
        },
        {
          "field": "action",
          "title": "Action in this setting"
        },
        {
          "field": "action_low",
          "title": "Base action"
        }
      ]
    }
  },
  "config": {
    "view": {
      "stroke": null
    }
  }
}'

'{
  "view": {
    "stroke": "transparent"
  },
  "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
  "arc": {},
  "area": {
    "line": true,
    "opacity": 0.6
  },
  "bar": {},
  "line": {
    "strokeWidth": 3,
    "strokeCap": "round",
    "strokeJoin": "round"
  },
  "point": {
    "filled": true,
    "size": 75
  },
  "rect": {},
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "fontSize": 12,
    "fill": "#605E5C"
  },
  "axis": {
    "ticks": false,
    "grid": false,
    "domain": false,
    "labelColor": "#605E5C",
    "labelFontSize": 12,
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleColor": "#0B2530",
    "titleFontSize": 16,
    "titleFontWeight": "normal"
  },
  "axisQuantitative": {
    "tickCount": 3,
    "grid": true,
    "gridColor": "#C8C6C4",
    "gridDash": [
      1,
      5
    ],
    "labelFlush": false
  },
  "axisX": {
    "labelPadding": 5
  },
  "axisY": {
    "labelPadding": 10
  },
  "header": {
    "titleFont": "din, wf_standard-font, helvetica, arial, sans-serif",
    "titleFontSize": 16,
    "titleColor": "#0B2530",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#605E5C"
  },
  "legend": {
    "titleFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "titleFontWeight": "bold",
    "titleColor": "#605E5C",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, helvetica, arial, sans-serif",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#605E5C",
    "symbolType": "circle",
    "symbolSize": 75
  }
}'
